cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// These doubles implement the Source/Lease contract in src/source.ts.
function fixture({ values = ['a', 'b', null], readError, closeError, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          if (readError) throw readError;
          return values.shift();
        },
        async close() {
          calls.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { calls, service: new EventService(source, mapper) };
}

async function rejectsWith(promise, expected) {
  await assert.rejects(promise, error => error === expected);
}

async function main() {
  const lazy = fixture();
  const unopened = lazy.service.stream();
  assert.deepEqual(lazy.calls, { opens: 0, reads: 0, closes: 0 });
  await unopened.return();
  assert.deepEqual(lazy.calls, { opens: 0, reads: 0, closes: 0 });

  const ordered = fixture();
  const stream = ordered.service.stream();
  assert.deepEqual(await stream.next(), { value: 'A', done: false });
  assert.deepEqual(ordered.calls, { opens: 1, reads: 1, closes: 0 });
  assert.deepEqual(await stream.next(), { value: 'B', done: false });
  assert.deepEqual(ordered.calls, { opens: 1, reads: 2, closes: 0 });
  assert.equal((await stream.next()).done, true);
  await stream.next();
  await stream.return();
  assert.deepEqual(ordered.calls, { opens: 1, reads: 3, closes: 1 });

  for (const closeFails of [false, true]) {
    const closeError = closeFails ? new Error('close') : undefined;
    for (const exit of ['exhaust', 'break', 'return', 'read', 'mapper', 'throw']) {
      const original = new Error(exit);
      const f = fixture({
        closeError,
        readError: exit === 'read' ? original : undefined,
        mapper: exit === 'mapper' ? () => { throw original; } : undefined,
      });
      const iterator = f.service.stream();
      const operation = (async () => {
        if (exit === 'exhaust' || exit === 'break') {
          const found = [];
          for await (const value of iterator) {
            found.push(value);
            if (exit === 'break') break;
          }
          assert.deepEqual(found, exit === 'break' ? ['A'] : ['A', 'B']);
        } else {
          await iterator.next();
          if (exit === 'return') await iterator.return();
          if (exit === 'throw') await iterator.throw(original);
        }
      })();
      if (['read', 'mapper', 'throw'].includes(exit)) {
        await rejectsWith(operation, original);
      } else if (closeFails) {
        await rejectsWith(operation, closeError);
      } else {
        await operation;
      }
      await iterator.next();
      await iterator.return();
      assert.equal(f.calls.opens, 1);
      assert.equal(f.calls.closes, 1);
      assert.equal(f.calls.reads, exit === 'exhaust' ? 3 : 1);
    }
  }

  // A thrown value need not be an Error, or even truthy.
  const f = fixture({ closeError: new Error('close') });
  const iterator = f.service.stream();
  await iterator.next();
  let caught = false;
  try { await iterator.throw(undefined); } catch (error) {
    caught = true;
    assert.equal(error, undefined);
  }
  assert.equal(caught, true);
  assert.equal(f.calls.closes, 1);

  const openError = new Error('open');
  const unavailable = new EventService({ open: async () => { throw openError; } });
  await rejectsWith(unavailable.stream().next(), openError);
}
module.exports = main();
EOF
